sys_script_include.script:
var OTPUtil = Class.create()
OTPUtil.prototype = {
    initialize: function () {},

    /**
     * Generates a random 6-digit numeric OTP and stores it directly
     * on the service_log record (NOT on asset_passport).
     *
     * @param {string} serviceLogSysId - sys_id of the service_log record
     * @returns {string} the generated 6-digit OTP code
     */
    generateOTP: function (serviceLogSysId) {
        var code = '' + Math.floor(100000 + Math.random() * 900000);

        var gr = new GlideRecord('x_1919710_refurt_0_service_log');
        if (gr.get(serviceLogSysId)) {
            gr.setValue('otp_code', code);
            gr.setWorkflow(false);
            gr.update();
        }

        return code;
    },

    /**
     * Validates the entered OTP against the stored otp_code on the
     * service_log record. On success, clears otp_code to empty so it
     * cannot be replayed (single-use).
     *
     * @param {string} serviceLogSysId - sys_id of the service_log record
     * @param {string} enteredOtp - the OTP the user entered
     * @returns {boolean} true if match, false otherwise
     */
    validateOTP: function (serviceLogSysId, enteredOtp) {
        var gr = new GlideRecord('x_1919710_refurt_0_service_log');
        if (!gr.get(serviceLogSysId)) {
            return false;
        }

        var storedCode = gr.getValue('otp_code');
        if (!storedCode || storedCode.toString() !== enteredOtp.toString()) {
            return false;
        }

        // Match! Clear otp_code so it can't be reused
        gr.setValue('otp_code', '');
        gr.setWorkflow(false);
        gr.update();

        return true;
    },

    type: 'OTPUtil',
}
